import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: parse tenant from subdomain
app.use((req, res, next) => {
  const host = req.headers.host || '';
  req.tenantId = host.split('.')[0] || 'default';
  next();
});

// Search endpoint with full-text search
app.get('/api/v2/documents/search', async (req, res) => {
  const { q, fields, sort_by, page = 1, limit = 20 } = req.query;

  if (!q || q.length > 500) {
    return res.status(400).json({ error: 'Invalid query' });
  }

  // Validate fields parameter
  const allowedFields = ['title', 'body', 'author', 'created_at', 'category'];
  let selectFields = 'id, title, body_preview, author, created_at';
  if (fields) {
    const requested = fields.split(',').map(f => f.trim());
    const valid = requested.filter(f => allowedFields.includes(f));
    if (valid.length > 0) selectFields = 'id, ' + valid.join(', ');
  }

  // Build sort clause - vulnerable to SQL injection
  let orderClause = 'created_at DESC';
  if (sort_by) {
    // Developer attempted validation but only checks first character
    if (sort_by[0] === '-' || sort_by[0] === '+' || /^[a-z]/.test(sort_by)) {
      const direction = sort_by[0] === '-' ? 'DESC' : 'ASC';
      const field = sort_by.replace(/^[+-]/, '');
      // VULNERABLE: field is interpolated without parameterization
      orderClause = `${field} ${direction}`;
    }
  }

  const offset = (parseInt(page) - 1) * parseInt(limit);

  try {
    const query = `
      SELECT ${selectFields},
             ts_rank(search_vector, plainto_tsquery('english', $1)) as relevance
      FROM documents
      WHERE tenant_id = $2
        AND search_vector @@ plainto_tsquery('english', $1)
      ORDER BY ${orderClause}
      LIMIT $3 OFFSET $4
    `;

    const result = await pool.query(query, [q, req.tenantId, parseInt(limit), offset]);

    // Log search for analytics
    await pool.query(
      'INSERT INTO search_log (tenant_id, query_text, result_count, ts) VALUES ($1, $2, $3, NOW())',
      [req.tenantId, q, result.rows.length]
    );

    res.json({
      results: result.rows,
      pagination: { page: parseInt(page), limit: parseInt(limit), total: result.rows.length }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', async (req, res) => {
  const { id } = req.params;
  if (!/^[0-9a-f-]{36}$/.test(id)) {
    return res.status(400).json({ error: 'Invalid document ID' });
  }

  try {
    const result = await pool.query(
      'SELECT id, title, body, author, created_at, category FROM documents WHERE id = $1 AND tenant_id = $2',
      [id, req.tenantId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Failed to retrieve document' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(8080, () => console.log('Document search service on :8080'));
